from math import isclose

def is_right_triangle_angles(alpha, beta, gamma, *, tol=1e-9):
    angles = (alpha, beta, gamma)
    if min(angles) <= 0:
        return False
    return isclose(sum(angles), 180.0, abs_tol=tol) and any(isclose(x, 90.0, abs_tol=tol) for x in angles)
